class Solution {
public:
    std::string findTheString(std::vector<std::vector<int>>& lcp) {
        int n = lcp.size();
        std::string word(n, ' ');
        char curr_char = 'a';
        for (int i = 0; i < n; ++i) {
            if (word[i] == ' ') {
                if (curr_char > 'z') return "";
                char ch = curr_char++;
                for (int j = i; j < n; ++j) {
                    if (lcp[i][j] > 0) {
                        word[j] = ch;
                    }
                }
            }
        }
        std::vector<std::vector<int>> dp(n + 1, std::vector<int>(n + 1, 0));
        for (int i = n - 1; i >= 0; --i) {
            for (int j = n - 1; j >= 0; --j) {
                if (word[i] == word[j]) {
                    dp[i][j] = dp[i + 1][j + 1] + 1;
                }
                if (dp[i][j] != lcp[i][j]) return "";
            }
        }
        return word;
    }
};

class Solution {
    public String findTheString(int[][] lcp) {
        int n = lcp.length;
        char[] word = new char[n];
        char currChar = 'a';
        for (int i = 0; i < n; i++) {
            if (word[i] == 0) {
                if (currChar > 'z') return "";
                char ch = currChar++;
                for (int j = i; j < n; j++) {
                    if (lcp[i][j] > 0) {
                        word[j] = ch;
                    }
                }
            }
        }
        int[][] dp = new int[n + 1][n + 1];
        for (int i = n - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                if (word[i] == word[j]) {
                    dp[i][j] = dp[i + 1][j + 1] + 1;
                }
                if (dp[i][j] != lcp[i][j]) return "";
            }
        }
        return new String(word);
    }
}

var findTheString = function(lcp) {
    const n = lcp.length;
    const word = new Array(n).fill('');
    let currCode = 97;
    for (let i = 0; i < n; i++) {
        if (!word[i]) {
            if (currCode > 122) return "";
            const ch = String.fromCharCode(currCode++);
            for (let j = i; j < n; j++) {
                if (lcp[i][j] > 0) {
                    word[j] = ch;
                }
            }
        }
    }
    const dp = Array.from({ length: n + 1 }, () => new Int32Array(n + 1));
    for (let i = n - 1; i >= 0; i--) {
        for (let j = n - 1; j >= 0; j--) {
            if (word[i] === word[j]) {
                dp[i][j] = dp[i + 1][j + 1] + 1;
            }
            if (dp[i][j] !== lcp[i][j]) return "";
        }
    }
    return word.join('');
};
